*{box-sizing:border-box} :root{--ink:#f7f5ec;--muted:#a9aaa0;--acid:#d5f064;--orange:#f27643;--panel:rgba(17,23,19,.89)} html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101611;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}.game-shell{position:relative;width:100vw;height:100dvh;min-height:500px;overflow:hidden;background:#20291d}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 48%,transparent 40%,rgba(8,13,9,.16) 100%),linear-gradient(180deg,rgba(8,12,9,.42),transparent 22%,transparent 75%,rgba(8,12,9,.36)}.topbar{height:76px;position:absolute;left:0;right:0;top:0;padding:0 45px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.1);background:linear-gradient(180deg,rgba(13,18,14,.62),transparent);z-index:2}.brand{display:flex;align-items:center;gap:12px;color:#f8f6ee;text-decoration:none;font-family:'Barlow Condensed',sans-serif;font-size:19px;font-weight:900;letter-spacing:1.9px}.brand-mark{width:34px;height:34px;display:grid;place-items:center;background:var(--acid);color:#182019;font-size:13px;letter-spacing:-.7px;transform:skew(-8deg)}.brand-light{font-weight:500;color:#c5c6bb;margin-left:4px}.event-label{position:absolute;left:50%;transform:translateX(-50%);font:10px 'DM Mono',monospace;letter-spacing:1.8px;color:#dcddd4}.event-label i,.clock-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--acid);margin-right:9px;vertical-align:1px;box-shadow:0 0 12px rgba(213,240,100,.7)}.event-label b{color:#77796e;margin:0 7px}.sound-button{background:none;border:1px solid rgba(255,255,255,.24);padding:9px 12px;display:flex;gap:9px;align-items:center;color:#ddd;font:9px 'DM Mono',monospace;letter-spacing:1px;cursor:pointer}.sound-icon{font-size:14px;color:var(--acid)}.race-hud{position:absolute;left:42px;right:42px;top:102px;display:flex;align-items:flex-start;z-index:1;opacity:0;transition:opacity .35s;pointer-events:none}.race-hud.active{opacity:1}.hud-card{background:rgba(12,18,14,.76);border:1px solid rgba(255,255,255,.12);padding:13px 17px 12px;min-width:110px;backdrop-filter:blur(8px)}.hud-kicker,.menu-foot,.track-pick-label,.surface-label,.track-label,.hud-card .place-change,.race-clock small{font:9px 'DM Mono',monospace;letter-spacing:1.25px;color:#b1b5a8}.hud-card>div{margin:3px 0 1px}.hud-card strong{font:700 33px 'Barlow Condensed',sans-serif;line-height:1}.hud-card small{font:11px 'DM Mono',monospace;color:#a6a99f}.place-change{font-size:8px!important;color:var(--acid)!important}.lap-card{margin-left:7px;min-width:100px}.lap-progress{height:3px;background:#4a4b41;margin-top:8px!important;width:100%}.lap-progress i{height:100%;width:0;display:block;background:var(--acid);transition:width .1s}.race-clock{position:absolute;left:50%;transform:translateX(-50%);top:9px;text-align:center;min-width:110px;font:14px 'DM Mono',monospace;color:#f4f4eb}.race-clock small{display:block;font-size:8px;margin-top:4px}.speed-card{margin-left:auto;text-align:right;background:rgba(12,18,14,.76);border:1px solid rgba(255,255,255,.12);padding:10px 15px 9px;width:155px}.speed-readout strong{font:700 31px 'Barlow Condensed',sans-serif}.speed-readout span{font:9px 'DM Mono',monospace;color:var(--acid);margin-left:5px}.speed-bar{width:100%;height:3px;background:#505348;margin:3px 0 7px}.speed-bar i{display:block;height:100%;width:0;background:var(--acid)}.surface-label{font-size:8px}.track-label{position:absolute;right:44px;bottom:32px;display:flex;align-items:center;gap:8px;background:rgba(12,18,14,.68);padding:9px 12px;border:1px solid rgba(255,255,255,.14);font-size:9px}.track-label-dot{width:7px;height:7px;border-radius:50%;background:#dfad64}.track-label small{color:#f7f2e4;font-size:8px;border-left:1px solid #65645b;padding-left:9px}.controls-hint{position:absolute;bottom:34px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:6px;color:#d4d7cc;font:9px 'DM Mono',monospace;letter-spacing:.8px;white-space:nowrap;opacity:0;transition:opacity .3s}.controls-hint.active{opacity:.9}.controls-hint b{color:#77796e;margin:0 7px}.keycap{border:1px solid rgba(255,255,255,.38);border-bottom-width:2px;min-width:19px;height:20px;display:inline-grid;place-items:center;font-size:9px;color:#f6f7ee}.keycap-wide{padding:0 6px}.countdown{position:absolute;top:44%;left:50%;transform:translate(-50%,-50%);font:900 clamp(90px,18vw,220px)/.8 'Barlow Condensed',sans-serif;color:var(--acid);text-shadow:0 6px 35px rgba(0,0,0,.7);font-style:italic;pointer-events:none}.overlay{position:absolute;inset:0;z-index:3;display:flex;align-items:center;justify-content:flex-start;background:linear-gradient(90deg,rgba(11,17,13,.93) 0%,rgba(12,18,14,.88) 35%,rgba(12,18,14,.22) 70%,rgba(12,18,14,.04) 100%);transition:opacity .45s,visibility .45s}.menu-overlay{padding:84px max(8vw,48px) 25px}.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.menu-content{width:min(440px,47vw);position:relative;z-index:1}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:1.6px;color:var(--acid);display:flex;align-items:center;gap:9px}.eyebrow-line{width:24px;height:1px;background:var(--acid)}h1{font:900 clamp(67px,8vw,108px)/.75 'Barlow Condensed',sans-serif;letter-spacing:-2px;margin:20px 0 13px;color:#f7f5ec;font-style:italic}h1 span{color:var(--acid)}.hero-copy{font-size:14px;color:#d0d1c7;margin:17px 0 30px}.track-pick-label{display:flex;justify-content:space-between;margin-bottom:9px;font-size:9px}.track-pick-label span{color:#73786c}.track-options{display:grid;gap:7px}.track-option{height:61px;width:100%;padding:6px 12px 6px 7px;display:flex;align-items:center;gap:12px;background:rgba(245,245,230,.055);border:1px solid rgba(235,240,221,.15);text-align:left;cursor:pointer;transition:.18s}.track-option:hover{background:rgba(255,255,255,.1)}.track-option.selected{border-color:var(--acid);background:rgba(213,240,100,.08)}.track-thumb{width:75px;height:45px;display:block;position:relative;overflow:hidden;background:#414731}.track-thumb:before{content:'';position:absolute;width:60px;height:28px;border:8px solid #a87b4c;border-radius:50%;left:7px;top:8px;box-shadow:0 0 0 2px #584433}.track-thumb:after{content:'';position:absolute;width:24px;height:8px;border-radius:50%;background:#46513b;left:25px;top:18px}.mud-thumb{background:#374233}.mud-thumb:before{border-color:#5a493a;box-shadow:0 0 0 2px #282922}.mud-thumb:after{background:#536044}.track-info{display:grid;gap:4px;flex:1}.track-info b{font:700 14px 'Barlow Condensed',sans-serif;letter-spacing:.9px}.track-info small{font:8px 'DM Mono',monospace;letter-spacing:.7px;color:#a9aea0}.checkmark{width:19px;height:19px;border:1px solid #686d60;border-radius:50%;display:grid;place-items:center;font-size:11px;color:transparent}.selected .checkmark{background:var(--acid);border-color:var(--acid);color:#1b2318}.start-button{margin-top:13px;width:100%;height:48px;border:0;background:var(--acid);color:#1b2418;display:flex;justify-content:space-between;align-items:center;padding:0 17px;cursor:pointer;font:700 11px 'DM Mono',monospace;letter-spacing:1.35px;transition:background .16s,transform .16s}.start-button:hover{background:#e5ff83;transform:translateY(-1px)}.start-button b{font-size:18px}.menu-foot{display:flex;justify-content:space-between;margin-top:13px;font-size:8px;color:#8f9488;letter-spacing:.8px}.menu-stats{position:absolute;right:9%;bottom:11%;display:flex;gap:40px;border-top:1px solid rgba(255,255,255,.3);padding-top:12px}.menu-stats div{display:grid;gap:1px}.menu-stats strong{font:700 23px 'Barlow Condensed',sans-serif}.menu-stats span{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#c2c6b9}.result-overlay{justify-content:center;background:rgba(9,14,10,.75);backdrop-filter:blur(8px)}.result-card{width:min(420px,90vw);padding:32px;background:rgba(19,25,20,.96);border:1px solid rgba(255,255,255,.18);box-shadow:0 25px 100px #0008}.result-card h2{font:900 48px/.9 'Barlow Condensed',sans-serif;font-style:italic;margin:18px 0 8px}.result-card>p{color:#c1c5b9;font-size:13px}.result-stats{display:grid;grid-template-columns:repeat(3,1fr);margin:25px 0;border-top:1px solid #42483e;border-bottom:1px solid #42483e;padding:13px 0;gap:12px}.result-stats div{display:grid;gap:5px}.result-stats span{font:8px 'DM Mono',monospace;color:#a6ab9d;letter-spacing:1px}.result-stats b{font:600 16px 'Barlow Condensed',sans-serif}.result-card .start-button{margin-top:0}.back-button{display:block;border:0;background:none;color:#b4baad;margin:14px auto 0;font:9px 'DM Mono',monospace;letter-spacing:1.2px;cursor:pointer}.toast{position:absolute;z-index:4;left:50%;top:20%;transform:translate(-50%,-10px);padding:10px 18px;background:rgba(18,23,17,.92);border:1px solid #d5f064;color:#e5efcc;font:10px 'DM Mono',monospace;letter-spacing:1px;opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.touch-controls{display:none;position:absolute;z-index:2;inset:auto 18px 18px;justify-content:space-between;align-items:flex-end;pointer-events:none}.touch-steer,.touch-pedals{display:flex;gap:9px;pointer-events:auto}.touch-controls button{height:58px;min-width:58px;border:1px solid #ffffff4a;background:#111a12c9;color:#fff;font:700 14px 'DM Mono',monospace;touch-action:none}.touch-pedals button{min-width:68px;font-size:9px;letter-spacing:1px}.touch-pedals button:last-child{background:#d5f064;color:#1c2619;border-color:#d5f064}.touch-controls button.active{filter:brightness(1.35);transform:scale(.97)}
@media(max-width:760px){.topbar{height:57px;padding:0 17px}.brand{font-size:16px;gap:8px}.brand-mark{width:29px;height:29px}.event-label{display:none}.sound-button{padding:7px 8px;font-size:8px}.race-hud{left:12px;right:12px;top:68px}.hud-card{padding:9px 11px;min-width:80px}.hud-card strong{font-size:27px}.lap-card{min-width:78px;margin-left:5px}.race-clock{top:auto;bottom:-32px;font-size:12px}.race-clock small{display:none}.speed-card{width:108px;padding:8px 10px}.speed-readout strong{font-size:25px}.surface-label{font-size:7px}.track-label{right:12px;bottom:94px;padding:7px 9px;font-size:8px}.controls-hint{display:none}.touch-controls{display:flex}.overlay{background:linear-gradient(90deg,rgba(11,17,13,.95),rgba(12,18,14,.82) 75%,rgba(12,18,14,.4))}.menu-overlay{padding:72px 22px 18px;align-items:center}.menu-content{width:min(430px,100%)}h1{font-size:76px;margin:17px 0 12px}.hero-copy{margin:14px 0 22px;font-size:13px}.menu-stats{display:none}.track-option{height:57px}.menu-foot{font-size:7px}.result-card{padding:26px}.result-card h2{font-size:42px}}
@media(max-height:650px) and (min-width:761px){.menu-overlay{padding-top:65px}.menu-content{transform:scale(.88);transform-origin:left center}.topbar{height:60px}.race-hud{top:75px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 1200, H = 760, CX = 600, CY = 380, TRACK_W = 132, HALF = TRACK_W / 2;
  const TAU = Math.PI * 2, N = 720;
  const $ = id => document.getElementById(id);
  const ui = {menu:$('menuOverlay'), result:$('resultOverlay'), hud:$('raceHud'), countdown:$('countdown'), hint:$('controlsHint'), position:$('position'), lap:$('lap'), lapProgress:$('lapProgress'), timer:$('timer'), speed:$('speed'), speedBar:$('speedBar'), surface:$('surfaceLabel'), trackLabel:$('trackLabel'), toast:$('toast')};
  const tracks = {
    dirt:{name:'RED ROCK OVAL',surface:'DIRT', maxSpeed:252, grip:.87, road:'#9a6840', shoulder:'#76523a', edge:'#4b392e', line:'#d8a56a', mud:false},
    mud:{name:'BLACKWATER BOWL',surface:'MUD',maxSpeed:211,grip:.66,road:'#51463a',shoulder:'#39392f',edge:'#272c25',line:'#817157',mud:true}
  };
  let track = tracks.dirt, selectedTrack = 'dirt', playing = false, started = false, finished = false;
  let dpr = 1, scale = 1, ox = 0, oy = 0, lastTime = 0, elapsed = 0, countdownUntil = 0, lapStarted = 0, bestLap = Infinity, raceTime = 0, lastUi = 0, cameraShake = 0, bumpToast = 0;
  let audioOn = true, audioCtx = null, cars = [], player = null, skidMarks = [], particles = [], gravel = [];
  const keys = Object.create(null), touch = {left:false,right:false,gas:false,brake:false};
  const rand = (a,b) => a + Math.random() * (b-a);
  const clamp = (v,a,b) => Math.max(a,Math.min(b,v));
  const mod = (v,n) => ((v%n)+n)%n;
  const nodes = [];
  let totalLength = 0;
  function pathPoint(u) {
    const t = u - Math.PI / 2;
    return {x:CX + 398*Math.cos(t) + 18*Math.cos(3*t), y:CY + 206*Math.sin(t) + 12*Math.sin(2*t)};
  }
  for(let i=0;i<=N;i++){
    const u=TAU*i/N, p=pathPoint(u);
    if(i){const prev=nodes[i-1];totalLength+=Math.hypot(p.x-prev.x,p.y-prev.y);}
    nodes.push({...p,u,s:totalLength});
  }
  function pointAt(s){
    s=mod(s,totalLength);let lo=0,hi=N;
    while(lo<hi){const m=(lo+hi)>>1;if(nodes[m].s<s)lo=m+1;else hi=m;}
    const b=nodes[lo],a=nodes[Math.max(0,lo-1)],f=(s-a.s)/Math.max(.001,b.s-a.s);
    const x=a.x+(b.x-a.x)*f,y=a.y+(b.y-a.y)*f,dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1;
    return {x,y,tx:dx/len,ty:dy/len,nx:-dy/len,ny:dx/len};
  }
  function nearest(x,y){
    let best=Infinity,idx=0;
    for(let i=0;i<N;i+=2){const p=nodes[i],d=(x-p.x)**2+(y-p.y)**2;if(d<best){best=d;idx=i;}}
    const a=nodes[idx],b=nodes[idx+1],dx=b.x-a.x,dy=b.y-a.y,f=clamp(((x-a.x)*dx+(y-a.y)*dy)/(dx*dx+dy*dy),0,1);
    const px=a.x+dx*f,py=a.y+dy*f,len=Math.hypot(dx,dy)||1;
    return {s:a.s+(b.s-a.s)*f,dist:Math.hypot(x-px,y-py),x:px,y:py,tx:dx/len,ty:dy/len,nx:-dy/len,ny:dx/len};
  }
  const colors=['#d95d39','#d6d5bd','#477c9d','#d5a636','#bd534c','#547b4d','#a9a49a','#67588d','#e07f35','#438a79','#b6c3c4','#9d513b'];
  function makeCar(i, progress, lane){
    const p=pointAt(progress),angle=Math.atan2(p.tx,-p.ty);
    return {id:i,player:i===0,x:p.x+p.nx*lane,y:p.y+p.ny*lane,angle,speed:0,progress,lap:0,lane,color:colors[i],damage:0,stun:0,hitCd:0,steer:0,boost:rand(.9,1.08),aiPhase:rand(0,TAU),wobble:rand(0,TAU),lastS:mod(progress,totalLength),collisions:0};
  }
  function makeGrid(){
    cars=[];
    // Twin-wide staggered grid; player starts sixth in the pack.
    const start=totalLength-93;
    for(let row=0;row<6;row++){
      const s=start-row*39;
      for(let col=0;col<2;col++){
        const idx=row*2+col, lane=(col===0?-25:25)+rand(-3,3);
        const c=makeCar(idx,s,lane);c.progress=s;
        if(idx>0){c.speed=0;c.lane+=rand(-4,4);}
        cars.push(c);
      }
    }
    player=cars[5];player.player=true;player.speed=0;player.progress=start-2*39;
    // Keep lanes clean around the player and give the grid a little personality.
    player.lane=23;
    cars.forEach(c=>{const p=pointAt(c.progress);c.x=p.x+p.nx*c.lane;c.y=p.y+p.ny*c.lane;c.angle=Math.atan2(p.tx,-p.ty);c.lastS=mod(c.progress,totalLength);});
    skidMarks=[];particles=[];elapsed=0;raceTime=0;bestLap=Infinity;finished=false;started=false;playing=true;lapStarted=0;lastTime=performance.now();
  }
  const bg=document.createElement('canvas');bg.width=W;bg.height=H;const bgc=bg.getContext('2d');
  function buildBackground(){
    bgc.fillStyle='#414c36';bgc.fillRect(0,0,W,H);
    let seed=81293;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
    for(let i=0;i<6200;i++){
      const x=random()*W,y=random()*H,r=.4+random()*2.2;
      bgc.globalAlpha=.06+random()*.13;bgc.fillStyle=random()>.48?'#c2bd81':'#18251b';
      bgc.beginPath();bgc.ellipse(x,y,r*1.7,r,random()*3.14,0,TAU);bgc.fill();
    }
    bgc.globalAlpha=1;
    // Infield and track apron details.
    for(let i=0;i<68;i++){
      const x=rand(115,1085),y=rand(105,655);
      const n=nearest(x,y);
      if(n.dist>103&&n.dist<182){bgc.fillStyle=Math.random()>.5?'#4b5437':'#343e30';bgc.globalAlpha=.6;bgc.beginPath();bgc.ellipse(x,y,rand(2,7),rand(1,3),rand(0,6),0,TAU);bgc.fill();}
    }
    bgc.globalAlpha=1;
  }
  buildBackground();
  function resize(){
    const rect=canvas.getBoundingClientRect();dpr=Math.min(window.devicePixelRatio||1,2);
    canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);
    scale=Math.min(canvas.width/W,canvas.height/H);ox=(canvas.width-W*scale)/2;oy=(canvas.height-H*scale)/2;
  }
  window.addEventListener('resize',resize);resize();
  function pathOnCanvas(c){c.beginPath();for(let i=0;i<nodes.length;i++){const p=nodes[i];if(i===0)c.moveTo(p.x,p.y);else c.lineTo(p.x,p.y);}c.closePath();}
  function ellipseIsland(c){c.beginPath();c.ellipse(CX,CY,327,133,-.025,0,TAU);c.closePath();}
  function drawTrack(){
    ctx.drawImage(bg,0,0);
    // Outer berm and the packed racing surface.
    pathOnCanvas(ctx);ctx.lineJoin='round';ctx.strokeStyle='#282d24';ctx.lineWidth=TRACK_W+42;ctx.stroke();
    pathOnCanvas(ctx);ctx.strokeStyle=track.edge;ctx.lineWidth=TRACK_W+23;ctx.stroke();
    pathOnCanvas(ctx);ctx.strokeStyle=track.shoulder;ctx.lineWidth=TRACK_W+7;ctx.stroke();
    pathOnCanvas(ctx);ctx.strokeStyle=track.road;ctx.lineWidth=TRACK_W-4;ctx.stroke();
    // Softer racing groove and rough shoulder streaks.
    pathOnCanvas(ctx);ctx.strokeStyle=track.mud?'rgba(152,132,103,.12)':'rgba(238,188,119,.15)';ctx.lineWidth=70;ctx.stroke();
    ctx.save();ctx.setLineDash([17,15]);ctx.lineWidth=3;ctx.strokeStyle=track.mud?'rgba(32,34,29,.28)':'rgba(62,42,29,.27)';pathOnCanvas(ctx);ctx.stroke();ctx.restore();
    // Rough dirt flecks on the wide circuit, deliberately sparse so the road reads cleanly.
    for(let i=0;i<260;i++){
      const s=i/260*totalLength,p=pointAt(s),side=(i%2?1:-1)*rand(39,70),x=p.x+p.nx*side,y=p.y+p.ny*side;
      ctx.globalAlpha=rand(.08,.27);ctx.fillStyle=track.mud?(i%3?'#1e211c':'#b09a78'):(i%3?'#503c2d':'#e6bb7c');
      ctx.beginPath();ctx.ellipse(x,y,rand(1,4),rand(.7,1.8),Math.atan2(p.ty,p.tx),0,TAU);ctx.fill();
    }
    ctx.globalAlpha=1;
    // Infield island, grass patches and scattered infield tire stacks.
    ellipseIsland(ctx);ctx.fillStyle='#566344';ctx.fill();ctx.strokeStyle='#303c2c';ctx.lineWidth=8;ctx.stroke();
    ctx.save();ctx.beginPath();ctx.ellipse(CX,CY,315,121,-.025,0,TAU);ctx.clip();
    for(let i=0;i<540;i++){let x=CX+rand(-315,315),y=CY+rand(-125,125);if(((x-CX)/325)**2+((y-CY)/133)**2<.92){ctx.globalAlpha=rand(.08,.25);ctx.fillStyle=Math.random()>.5?'#a1a06b':'#283a2b';ctx.beginPath();ctx.ellipse(x,y,rand(2,8),rand(1,3),rand(0,6),0,TAU);ctx.fill();}}
    ctx.globalAlpha=1;ctx.restore();
    // Tire stacks on both edges.
    for(let i=0;i<92;i++){
      const p=pointAt(i/92*totalLength),side=i%2?1:-1,x=p.x+p.nx*side*88,y=p.y+p.ny*side*88;
      ctx.fillStyle='#20241e';ctx.beginPath();ctx.ellipse(x+2,y+3,7,5,0,0,TAU);ctx.fill();ctx.fillStyle=i%4===0?'#d7cba7':'#3c4038';ctx.beginPath();ctx.ellipse(x,y,6,4.4,0,0,TAU);ctx.fill();ctx.strokeStyle='#191d19';ctx.lineWidth=1.5;ctx.stroke();
    }
    // Start/finish stripe across the track at the top bend.
    const p=pointAt(0),across=HALF-3;
    ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.atan2(p.ty,p.tx));
    for(let i=0;i<10;i++){ctx.fillStyle=i%2?'#f0eee3':'#282b25';ctx.fillRect(-6,-across+i*(across*2/10),12,across*2/10+1);}
    ctx.restore();
    // Small flags and marshals give the circuit a lived-in club-race feel.
    drawFlag(575,82,'#e7e2d0');drawFlag(1090,378,'#ed7247');drawFlag(111,492,'#d4eb67');
    // Direction arrow markers on apron.
    for(let i=0;i<8;i++){const p=pointAt(totalLength*(i+.48)/8),x=p.x+p.nx*100,y=p.y+p.ny*100;ctx.save();ctx.translate(x,y);ctx.rotate(Math.atan2(p.ty,p.tx));ctx.fillStyle='rgba(243,226,179,.43)';ctx.beginPath();ctx.moveTo(-7,-5);ctx.lineTo(3,-5);ctx.lineTo(3,-9);ctx.lineTo(11,0);ctx.lineTo(3,9);ctx.lineTo(3,5);ctx.lineTo(-7,5);ctx.closePath();ctx.fill();ctx.restore();}
  }
